styles:
/* Reset and Base */
*, *::before, *::after {
  box-sizing: border-box;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
  font-size: 16px;
  line-height: 1.6;
  color: #1a1a1a;
  background: #ffffff;
  margin: 0;
  padding: 40px;
  max-width: 800px;
  margin: 0 auto;
}

/* Note Header */
.note-header {
  margin-bottom: 32px;
  padding-bottom: 24px;
  border-bottom: 1px solid #e5e5e5;
}

.note-emoji {
  font-size: 48px;
  line-height: 1;
  margin-bottom: 16px;
  display: block;
}

img.note-emoji,
svg.note-emoji {
  width: 48px;
  height: 48px;
  object-fit: contain;
  margin: 0 0 16px 0;
  border-radius: 0;
}

.note-title {
  font-size: 32px;
  font-weight: 700;
  margin: 0 0 16px 0;
  color: #0a0a0a;
  line-height: 1.2;
}

.note-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  font-size: 14px;
  color: #666;
}

.note-meta-item {
  display: flex;
  align-items: center;
  gap: 6px;
}

.note-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 12px;
}

.tag {
  display: inline-block;
  padding: 4px 10px;
  background: #f0f0f0;
  border-radius: 4px;
  font-size: 13px;
  color: #555;
}

/* Content */
.note-content {
  line-height: 1.7;
}

/* Headings */
h1, h2, h3, h4, h5, h6 {
  margin-top: 32px;
  margin-bottom: 16px;
  font-weight: 600;
  line-height: 1.3;
  color: #0a0a0a;
}

h1 { font-size: 28px; }
h2 { font-size: 24px; border-bottom: 1px solid #eee; padding-bottom: 8px; }
h3 { font-size: 20px; }
h4 { font-size: 18px; }
h5 { font-size: 16px; }
h6 { font-size: 14px; color: #666; }

/* Paragraphs */
p {
  margin: 0 0 16px 0;
}

/* Links */
a {
  color: #0066cc;
  text-decoration: none;
}

a:hover {
  text-decoration: underline;
}

/* Wiki links (internal links shown as plain text) */
.wiki-link {
  color: #0066cc;
  background: #f0f7ff;
  padding: 1px 4px;
  border-radius: 3px;
}

/* Footnotes */
.footnote-ref {
  font-size: 0.75em;
  line-height: 0;
}

.footnotes {
  margin-top: 32px;
  padding-top: 16px;
  border-top: 1px solid #e5e5e5;
  font-size: 14px;
  color: #444;
}

.footnotes h2 {
  font-size: 16px;
}

.footnote-backref {
  text-decoration: none;
}

/* Lists */
ul, ol {
  margin: 0 0 16px 0;
  padding-left: 24px;
}

li {
  margin-bottom: 4px;
}

li > ul, li > ol {
  margin-top: 4px;
  margin-bottom: 4px;
}

/* Checkbox lists (task lists) */
ul.contains-task-list {
  list-style: none;
  padding-left: 0;
}

li.task-list-item {
  display: flex;
  align-items: flex-start;
  gap: 8px;
}

li.task-list-item input[type="checkbox"] {
  margin-top: 5px;
}

/* Code */
code {
  font-family: 'SF Mono', 'Fira Code', 'Consolas', monospace;
  font-size: 14px;
  background: #f5f5f5;
  padding: 2px 6px;
  border-radius: 4px;
}

pre {
  background: #f5f5f5;
  padding: 16px;
  border-radius: 8px;
  overflow-x: auto;
  margin: 0 0 16px 0;
}

pre code {
  background: none;
  padding: 0;
  font-size: 14px;
  line-height: 1.5;
}

/* Blockquotes */
blockquote {
  margin: 0 0 16px 0;
  padding: 12px 20px;
  border-left: 4px solid #ddd;
  background: #fafafa;
  color: #555;
}

blockquote p:last-child {
  margin-bottom: 0;
}

/* Tables */
table {
  width: 100%;
  border-collapse: collapse;
  margin: 0 0 16px 0;
  font-size: 15px;
}

th, td {
  border: 1px solid #ddd;
  padding: 10px 12px;
  text-align: left;
}

th {
  background: #f5f5f5;
  font-weight: 600;
}

tr:nth-child(even) {
  background: #fafafa;
}

/* Horizontal rule */
hr {
  border: none;
  border-top: 1px solid #e5e5e5;
  margin: 32px 0;
}

/* Images */
img {
  max-width: 100%;
  height: auto;
  border-radius: 8px;
  margin: 16px 0;
}

/* Print styles */
@media print {
  body {
    padding: 0;
    font-size: 12pt;
  }

  .note-header {
    page-break-after: avoid;
  }

  h1, h2, h3, h4, h5, h6 {
    page-break-after: avoid;
  }

  pre, blockquote, table {
    page-break-inside: avoid;
  }

  a {
    color: #000;
    text-decoration: underline;
  }

  .wiki-link {
    background: none;
    color: #000;
  }
}

